def control(obs):
    lm = obs.get('local_map') or {}
    L = lm.get('left_rail') or []
    R = lm.get('right_rail') or []
    def interp(points, u):
        pts = sorted((float(p[0]), float(p[1])) for p in points if len(p) >= 2)
        if not pts: return None
        if u <= pts[0][0]: return pts[0][1]
        if u >= pts[-1][0]: return pts[-1][1]
        for (u0,v0),(u1,v1) in zip(pts,pts[1:]):
            if u0 <= u <= u1:
                f=(u-u0)/(u1-u0)
                return v0+f*(v1-v0)
        return None
    vals=[]
    for u in (4.0,6.0,8.0):
        a,b=interp(L,u),interp(R,u)
        if a is not None and b is not None: vals.append((u,(a+b)/2))
    target=sum(v for _,v in vals)/len(vals) if vals else 0.0
    hitch=float(obs.get('hitch_deg',0.0))
    steer=max(-22.0,min(22.0,-4.2*target+0.42*hitch))
    speed=-0.85 if abs(hitch)<32 else -0.55
    return (steer,speed)

